import sys

def lcm(a, b):
    return a * b // math.gcd(a, b)

def solve(n, m, k, nums):
    mod = 10**9 + 7
    total_sum = sum(nums)
    num_same_segment = total_sum % k

    if num_same_segment == 0:
        return total_sum // k

    valid_counts = {}
    cur_val = 0
    cur_cycles = 0

    for num in nums:
        cur_val = (cur_val * 10 + num) % k
        if cur_val in valid_counts:
            cur_cycles = (cur_cycles + valid_counts[cur_val]) % mod
            valid_counts[cur_val] = 0
        valid_counts[cur_val] += 1

    return (cur_cycles * total_sum) % mod

def main():
    input = sys.stdin.read
    data = input().split()
    n, m, k = map(int, data[0:3])
    nums = list(map(int, data[3:2*n+3])) + data[2*n+3:]

    result = solve(n, m, k, nums[:-1])
    print(result % (10**9 + 7))

if __name__ == '__main__':
