    stack = [[vertex, ""] for vertex in range(n)]

    visited = set()

    while stack:
        vertex, path = stack.pop()

        label_str = path
        label_str = ''.join(label[vertex:])

        if vertex in visited:
            continue

        visited.add(vertex)
        if is_palindrome(label_str):
