    min_ind = 0
    max_ind = N - 1
    for j in range(i - 1, i + 2):
        idx = j if i != j else idx + 1 # Reverse order
        if abs(idx) % 2:
            continue
        if p[j] >= min_val:
            min_ind = idx
        if p[j] <= max_val:
            max_ind = idx
    j_odd = min_ind
    j_even = max_ind
    if abs(j_odd - j_even) % 3 or abs(j_odd - j_even) == 1 or 4 < abs(j_odd - j_even) <= 7:
        return False
    n = abs(j_odd - j_even) // 3
    p[i + n] = p[i]
    if abs(min_ind - max_ind) % 3 or abs(min_ind - max_ind) == 1 or 4 < abs(min_ind - max_ind) <= 7:
        return False
    m = abs(min_ind - max_ind) // 3
    if p[0] < p[0] % 2 + n:
        m += 1
    if p[N - 1] < p[N - 1] % 2 + m:
        m += 1
    odd_prefix = max_ind // 2 + 1
    odd_suffix = min_ind // 2
    even_prefix = min_ind if odd_prefix % 2 == 0 else min_ind - 1
    even_suffix = max_ind if odd_suffix % 2 == 0 else max_ind - 1
    for i in range(odd_prefix, odd_suffix + 1, 2):
        for j in range(even_prefix, even_suffix + 1, 2):
            if i < j:
                pm_i = max(p[i: j])
                for k in range(i, j):
                    if p[k] == pm_i:
                        p[i:k] = reversed(p[i:k])
    p[i] = p[min_ind - j_odd]
    p[i + n] = p[max_ind - j_even]
    return True

