from collections import defaultdict

def find_path(graph, start, end):
    path = []
    visited = set()
    stack = [start]

    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        path.append(node)
        if node == end:
            break
        stack.extend(graph[node] - visited)

    return path if path and path[-1] == end else []

def find_best_path(graph, start, end, min_duration):
    visited = set([start])
    pq = [(0, start)]

    while pq:
        duration, node = heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        for next_node, duration in graph[node].items():
            if duration < min_duration:
                del graph[node][next_node]
            if next_node not in visited and duration < min_duration:
                heappush(pq, (duration + 2, next_node))
                visited.add(next_node)
    return visited

def optimal_solution(n, edges, min_duration):
    graph = defaultdict(dict)
    for a, b in edges:
        graph[a][b] = 1

    for start in range(1, n + 1):
        best_path = find_best_path(graph, start, start, min_duration)
        if not best_path:
            return "No"

    return "Yes\n" + "\n".join(f"{duration}" for duration in best_path)

