import sys

def dfn(k, n, mod):
    if n % k != 0:
        return 0

    total = 1
    remain = 0
    i = 2
    while i * i <= n:
        if n % i == 0:
            a = gcd(i, n)
            while n % i == 0:
                n //= i
        if n == k:
            total += i
        elif i != k and (n % k == 0 or remain == 0):
            total *= i
        remain *= i
        if n <= k:
            total = (total - remain) % mod
    if n >= k:
        total = (total - remain) % mod
    return total

def super_function(n, k, mod):
    @lru_cache(maxsize=None)
    def dfs(n, k):
        if n <= 1 or not k:
            return 0
        total = 0
        dp = 1
        for i in range(1, n):
            if (n - 1) % i == 0:
                dp = (dp - 1) % mod
                break
        for i in range(2, int((n-2) ** 0.5) + 2):
            if n % i == 0:
                dp = (dp - 1) % mod
                while n % i == 0:
                    n //= i
        if n >= k:
            dp = (dp - 1) % mod
        return (n - 1) // k + dfs(n // k + 1, k) + dp

    return dfs(n, k) % mod

