def weirdness_sum(A):
    n = len(A)
    dp = [[0] * (n+1) for _ in range(n+1)]
    pre_count = [0] * (n+1)

    for i in range(n):
        dp[i+1][i+1] = A[i]
        pre_count[i+1] = pre_count[i] + A[i]

    for length in range(2, n+1):
        for l in range(n-length+1):
            r = l + length - 1
            for i in range(l, r+1):
                # Calculate how many times A[i] occurs in the subarray [l, r]
                occurrences = pre_count[r+1] - pre_count[i]
                dp[l][r+1] += A[i] if A[i] == occurrences else 0
                dp[l][r+1] %= (10**9 + 7)

    return sum(dp[0][i:] for i in range(1, n+1))

def total_weirdness(A):
    odd_sum = sum(dp[i][i:] for i in range(1, len(A)+1))
    even_sum = sum(dp[0][i:] for i in range(1, len(A)+1))
    sum_of_smaller = 0
    for i in range(1, len(A)):
        if dp[0][i] & 1 == 1:
            sum_of_smaller += (odd_sum - dp[0][i])
        else:
            sum_of_smaller += (even_sum - dp[0][i])
    return sum_of_smaller

