import bisect

def sum_weirdness(arr):
    n = len(arr)
    dp = [0] * (n + 1)
    dp[0] = arr[0]
    for i in range(1, n):
        dp[i] = dp[i-1]
        bisect.insort_left(dp, dp[i])

    total_sum = 0
    for L in range(1, n + 1):
        for R in range(L, n + 1):
            weirdness = 0
            for i in range(L, R):
                if i == R or dp[i] != arr[i]:
                    break
                if dp[i] == arr[i]:
                    weirdness += 1
            total_sum += weirdness * (R - L + 1) // 2

    return total_sum

