def max_happiness(N: int, M: int, A: List[int], B_values: List[List[int]]) -> int:
    distances = []
    max_distances = 0
    for a in A:
        max_distances = max(max_distances, a)
    for i in range(N - 1):
        distance = A[i + 1] - A[i]
        distances.append((distance, i + 1))
        distances.append((distance, N - (i + 1)))
    distances.sort()

    happiness_scores = [[None for _ in range(max_distances + 1)] for _ in range(M + 1)]
    used_tickets = [False for _ in range(M + 1)]

    # Calculate maximum happiness
    for i in range(M, 0, -1):
        for d, j in distances:
            if not used_tickets[i - d] and i - d >= 0:
                if happiness_scores[j][i - d] is None:
                    happiness_scores[j][i - d] = i - d
                else:
                    if happiness_scores[j][i - d] < i - d:
                        happiness_scores[j][i - d] = i - d
                        used_tickets[j] = True

    best_happiness = -float('inf')
    for i in range(M, -1, -1):
        for d, j in distances:
            if not used_tickets[i + d]:
                total_distances = sum(abs(A[i] - A[N - (i + j)]) for j in range(M - i))
                total_deliciousness = sum(B[j - i for j in range(d + 1, d + M + 1)], B[0 + i])
                if total_distances == 0:
                    best_happiness = max(best_happiness, total_deliciousness)

    return best_happiness

