from collections import defaultdict

def water_garden(size):
    results = []
    diagonal, plant_columns = create_diagonal_columns(size)

    for row in range(size):
        new_add_method = create_column_method(plant_columns)
        column_method = Q.create_column_method(row)
        for column in column_method:
            if column not in plant_columns:
                results.append(Q.empty_method)
                plant_columns.add(column)
            else:
                results.append(column_method[column])
                plant_columns.remove(column)
                diagonal[row - column] = 0

    return sum(len(column_method) for column_method in results) <= 50

def create_diagonal_columns(size):
    plant_columns = set(range(size))
    diagonal = 0
    plant_columns.clear()
    for row in range(size):
        if row > diagonal:
            delta = size - 1 - diagonal
            if delta > len(plant_columns):
                plant_columns.update(range(plant_columns[-1], delta - 1, -1))
        else:
            plant_columns.difference_update(range(row + 1, diagonal))
        plant_columns.difference_update(range(row - diagonal, size))
        diagonal = size - 1 - diagonal
    return diagonal, plant_columns

@lru_cache(maxsize=128)
def Q.create_column_method(row):
    if row in plant_columns:
        return result[row]
    result[row] = []

@lru_cache(maxsize=128)
def create_column_method(plant_columns):
    if not plant_columns:
        return []

    if len(plant_columns) == 1:
        plant_columns.pop()
        return [0, plant_columns.pop()]

    column_method = defaultdict(list)
    for column in plant_columns:
        result = column_method[(row, column)]
        for result_row in Q.empty_method:
            column_method[(result_row, column)] = result_row + 1
    return plant_columns.copy()

