    events = []
    storage_deck = [(float('inf'), float('inf'), None)]
    destinations = [(0, float('inf'), None)]
    last_time = 0

    for _ in range(n + 1):
        time, person = map(int, input().split())
        events.append((time, person))
        last_time = max(last_time, time)

    tea_time = int(input())

    for i, (time, person) in enumerate(events):
        if person == 'P':
            # Store at Wise R
            while storage_deck[0][0] + d <= time:
                heappush(destinations, (storage_deck[0][1] + c * (time - storage_deck[0][0]), storage_deck[0][2], storage_deck[0][0]))
            last_needed_time = max(storage_deck[0][0], time - c)
            heappush(storage_deck, (time - last_needed_time, time, person))

        else:
            # Send via Friendly O with distance
            last_needed_time = max(storage_deck[0][0] + d, tea_time - last_time)
            heappush(destinations, (last_needed_time, None, 'W'))

            while storage_deck[0][0] < time + d:
                heappush(destinations, (storage_deck[0][1] + c * (time + d - storage_deck[0][0]), storage_deck[0][2], storage_deck[0][0]))
            last_needed_time = max(storage_deck[0][0], tea_time + c - last_time)
            heappush(storage_deck, (time + d - last_needed_time, time, person))
            heappop(storage_deck)

    return min_time(0)

def min_time(start_time):
    options = {time: start_time + d for time in range(tea_time)}
    while len(storage_deck) > 2:
        remaining = storage_deck.popleft()[2]
        if remaining is None:
            return float('inf')
        options[options[remaining] + d] = min(options[options[remaining] + d], options[remaining] + start_time, min_time(min_time(remaining)))
    return min(option + c for option in options.values())

