def is_inside(path, x, y):
    # Count intersections along the path from (x,y) to (0,0)
    intersections = 0
    for coords in path:
        dx = coords if coords[0] > x else (0, coords[0] - x)[coords[0] - x < 0]
        dy = coords if coords[1] > y else (0, coords[1] - y)[coords[1] - y < 0]

        # If there's any intersection point with slope dy/dx and (0,0)
        # we increment therefore we can use the counted intersections div dxy
        if dy != 0 and (x, dy - x)[dy - x < 0] == (0, 0)[dy == 0]:
            intersections += 1 if dy > 0 else -1
        x += dx

    # If there are even intersections, coordinate is inside the path, otherwise, outside
    return intersections % 2 == 1


