import math
from sympy import gcd
from functools import reduce

def super_function(N, K, M):
    # Function to calculate super function
    def sum_of_powers(i, k): 
        if k == 1: 
            return pow(i, 1)
        product = 1
        power = 1
        while k > 0:
            if (i % gcd(i, N)) == 0 and abs(pow(i, power, M) % M) < abs(pow(N, power, M) % M):
                product += pow(i // gcd(i, N), power + 1, M)
            power += 1
            k -= 1
        return product

    product = 1
    for i in range(1, N + 1):
        if gcd(i, M) == 1: 
            product += sum_of_powers(i, K)
        if product >= M:
            product %= M
    return product

