import sys

def can_improve_flight_time(n, m, flights):
    # Create a graph for the flights
    graph = {i: [] for i in range(1, n + 1)}
    for a, b in flights:
        graph[a].append(b)

    visited = [False] * (n + 1)
    available_flights = len([flight for time in range(3) for flight in flights if time <= 2])

    def dfs(city, memory):
        if city == n:
            return True
        if visited[city]:
            return False
        visited[city] = True
        for neighbor in graph[city]:
            # If we can get to the destination in time, return True
            if dfs(neighbor, memory and False):
                return True
        visited[city] = False
        return False

    available_end_points = 1
    for i in range(1, n + 1):
        if dfs(i, False):
            available_end_points += 1
            dfs(i, False)

    # If there's at least one cycle in the graph, no improvement is possible
    if available_end_points == 1:
        return "No"

    minimum_timestamp = sys.maxsize
    for i in range(1, n + 1):
        for flight_duration in range(1, 3):
            if dfs(i, True):
                time_taken = flight_duration * available_flights
                if time_taken < minimum_timestamp:
                    minimum_timestamp = time_taken

    if minimum_timestamp == sys.maxsize:
        return "No"

    return "Yes\n"
