N = int(input())
p = list(map(int, input().split()))

# Check if all numbers start from 1
if not all(p[i] == i + 1 for i in range(N)):
    print("No")

# Check if it's possible to reach the target state
target = [1] * N
i = 0
while i < N and target[i] != 0:
    if i == 0:
        j = 1
    else:
        k = N - 1
        while target[k] != 0 and p[k] != i + 1:
            k -= 1
        if k == i - 1:
            j = k + 1
        else:
            j = k
    if p[j] > p[i]:
        if j - i == 1:
            print("No")
            break
            # Reversing the target list
        else:
            temp = target[j]
            for k in range(j + 1, i):
                target[k] = target[k - 1]
            target[i - 1] = temp
            i -= 1
    else:
        target = [1] * N
        print("Yes")
        break
else:
    print("Yes")
